import * as React from "react"

import { cn } from "@/lib/utils"

type TranscriptCue = { id: string; start: number; end?: number; text: string; speaker?: string }
function transcriptCueAt(cues: TranscriptCue[], time: number): number {
  if (!Number.isFinite(time) || time < 0) return -1
  let result = -1
  for (let i = 0; i < cues.length; i++) {
    if (time >= cues[i].start && time < (cues[i].end ?? cues[i + 1]?.start ?? Infinity)) result = i
  }
  return result
}
const clock = (n: number) => `${Math.floor(n / 60)}:${String(Math.floor(n % 60)).padStart(2, "0")}`
type TranscriptProps = Omit<React.ComponentProps<"section">, "children"> & {
  cues: TranscriptCue[]
  currentTime?: number
  onSeek?: (seconds: number) => void
  label?: string
  formatTime?: (seconds: number) => string
  seekLabel?: (cue: TranscriptCue) => string
}

/** Can render as static server text. Add onSeek from a client to connect it to any recording. */
function Transcript({ cues, currentTime = 0, onSeek, label = "Transcript", formatTime = clock, seekLabel = (cue) => `Seek to ${clock(cue.start)}: ${cue.speaker ? `${cue.speaker}: ` : ""}${cue.text}`, className, ...props }: TranscriptProps) {
  if (new Set(cues.map((cue) => cue.id)).size !== cues.length || cues.some((cue, i) => !cue.id || !Number.isFinite(cue.start) || cue.start < 0 || (i > 0 && cue.start <= cues[i - 1].start) || (cue.end !== undefined && (!Number.isFinite(cue.end) || cue.end <= cue.start || (i + 1 < cues.length && cue.end > cues[i + 1].start)))))
    throw new RangeError("Transcript needs unique ids and ordered, finite, non-overlapping cue times")
  const active = transcriptCueAt(cues, currentTime)
  return <section {...props} data-slot="transcript" className={cn("db-transcript", className)} aria-label={props["aria-label"] ?? label}>
    <ol data-slot="transcript-cues">
      {cues.map((cue, i) => {
        const content = <><time data-slot="transcript-time" dateTime={`PT${cue.start}S`}><bdi dir="ltr">{formatTime(cue.start)}</bdi></time><span data-slot="transcript-words">{cue.speaker ? <span data-slot="transcript-speaker" className="db-reading">{cue.speaker}</span> : null}{cue.text}</span></>
        return <li key={cue.id} data-slot="transcript-cue" data-current={active === i ? "" : undefined}>{onSeek ? <button type="button" aria-current={active === i ? "true" : undefined} aria-label={seekLabel(cue)} onClick={() => onSeek(cue.start)}>{content}</button> : <div aria-current={active === i ? "true" : undefined}>{content}</div>}</li>
      })}
    </ol>
  </section>
}

export { Transcript, transcriptCueAt, type TranscriptProps, type TranscriptCue }

@layer components {
  /* A score opens around the spoken line; its timestamp is the small conductor in the margin. */
  .db-transcript { min-inline-size: 0; overflow-wrap: anywhere; container-type: inline-size; }
  .db-transcript ol { list-style: none; padding: 0; display: grid; }
  .db-transcript li { position: relative; border-block-start: var(--db-hairline) solid var(--db-rule); }
  .db-transcript li > :is(button, div) { display: grid; grid-template-columns: 3.5rem minmax(0, 1fr); gap: var(--db-space-4); inline-size: 100%; min-block-size: 64px; text-align: start; border: 0; background: none; padding: var(--db-space-4) 0; color: var(--db-pencil); }
  .db-transcript button { cursor: pointer; }
  .db-transcript button:hover { color: var(--db-graphite); }
  .db-transcript time { font-size: var(--db-pp); padding-block-start: 0.4em; line-height: var(--db-p-lh); font-variant-numeric: tabular-nums; }
  .db-transcript [data-slot="transcript-words"] { display: block; font-size: clamp(1.2rem, 4.5cqi, 1.65rem); font-weight: 300; line-height: 1.4; padding-inline-end: 0; transition: padding-block var(--db-andante) var(--db-exhale), font-size var(--db-andante) var(--db-spiccato), letter-spacing var(--db-andante) var(--db-exhale), color var(--db-moderato); }
  .db-transcript [data-slot="transcript-speaker"] { display: block; font-family: var(--db-expression); font-style: italic; font-size: var(--db-p); color: var(--db-pencil); margin-block-end: var(--db-space-2); }
  .db-transcript li[data-current] [data-slot="transcript-words"] { font-size: clamp(1.5rem, 6cqi, 2.4rem); letter-spacing: -0.035em; padding-block: var(--db-space-3); color: var(--db-ink); }
  .db-transcript li[data-current] time { color: var(--db-accent); }
  .db-transcript li::before { content: ""; position: absolute; inset-inline-start: 0; inset-block-start: 0; inline-size: 2rem; block-size: 0; border-inline-start: var(--db-hairline) solid var(--db-rule-strong); transition: block-size var(--db-andante) var(--db-spiccato), inline-size var(--db-andante) var(--db-exhale); pointer-events: none; }
  .db-transcript li[data-current]::before { block-size: var(--db-space-3); inline-size: 3rem; }
  @media (prefers-reduced-motion: reduce) { .db-transcript li::before, .db-transcript [data-slot="transcript-words"] { transition: none; } }
  @media (forced-colors: active) { .db-transcript li[data-current] time { color: Highlight; } }
}
